const GO_LIVE = '2026-08-03';                 // never touch leads created before today
const rows = $input.all().map(i => i.json);
const now = new Date();
const DONE = /^(replied|responded|dead|closed|won|lost|unsubscribed|do not contact|no contact)$/i;
const b64url = s => Buffer.from(s, 'utf8').toString('base64')
  .replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const out = [];
for (const r of rows) {
  if (DONE.test(String(r['Status']||'').trim())) continue;
  if (String(r['Day 5 Email Sent']||'').trim()) continue;
  const t = new Date(r['Timestamp']); if (isNaN(t)) continue;
  if (t.toISOString().slice(0,10) < GO_LIVE) continue;        // HARD CUTOFF
  const age = Math.floor((now - t) / 86400000);
  if (age < 5 || age > 30) continue;
  const email = String(r['Email']||'').trim(); if (!email) continue;
  const first = String(r['First Name']||'').trim() || 'there';
  const addr  = String(r['Searched Address']||'').trim();
  const street = addr ? addr.split(',')[0] : '';
  const subject = street ? ('Still happy to help with ' + street) : 'Still happy to help';
  const sig = '\n\nHector Meza\nBriggs Freeman Sotheby’s International Realty\n(214) 686-5641\nhectormeza.com';
  const body = (street
    ? 'Hey ' + first + ',\n\nI reached out last week about ' + addr + '. I would still like to put a real number together for you, I just want to hear about the house first so it actually means something.\n\nA quick call is easiest, but text or email works fine too. What is best for you?'
    : 'Hey ' + first + ',\n\nI reached out last week and wanted to follow up. I would still like to help you find the right place, I just want to hear what you are looking for first.\n\nA quick call is easiest, but text or email works fine too. What is best for you?') + sig;
  const mime = [
    'From: Hector Meza <hello@hectormeza.com>',
    'To: ' + email,
    'Subject: ' + subject,
    'MIME-Version: 1.0',
    'Content-Type: text/plain; charset="UTF-8"',
    '', body
  ].join('\r\n');
  out.push({ json: { email, first, subject, raw: b64url(mime), stamp: now.toISOString().slice(0,10) } });
}
return out;
